# RCMDS 1.1 | All-in-one installer for Windows PowerShell 5.1 and Windows Terminal.
# Installs per user. Does not need previous releases or permanent execution policy changes.
[CmdletBinding()]
param([switch]$NoLaunch)
$ErrorActionPreference='Stop'
if($PSVersionTable.PSEdition -ne 'Desktop' -or $PSVersionTable.PSVersion.Major -ne 5){throw 'Run this installer using Windows PowerShell 5.1 (powershell.exe), not pwsh.'}
$root=Join-Path $env:LOCALAPPDATA 'PSStyle'
$module=Join-Path $root 'PSStyle.psm1'
$stage=Join-Path $env:TEMP ('RCMDS-'+[guid]::NewGuid().ToString('N'))
$backup=Join-Path $root ('before-all-in-one-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6))
$profilePath=$PROFILE.CurrentUserAllHosts
$terminalPath=$null
$changedProfile=$false
$installed=$false
Write-Host 'RCMDS 1.1 | Installing...' -ForegroundColor Cyan
if(-not (Get-Command wt.exe -ErrorAction SilentlyContinue)){
    if(-not (Get-Command winget.exe -ErrorAction SilentlyContinue)){throw 'Install Windows Terminal from Microsoft Store, then run this installer again.'}
    Write-Host 'Windows Terminal not found; installing from the official winget source.' -ForegroundColor Cyan
    & winget.exe install --id Microsoft.WindowsTerminal --exact --source winget --accept-package-agreements --accept-source-agreements
    if(-not (Get-Command wt.exe -ErrorAction SilentlyContinue)){throw 'Windows Terminal is not available yet. Reopen PowerShell and run this installer again.'}
}
