eUFzc2V0cy9zbm93LXBpbGUucG5nUEsBAhQDFAAAAAgAahh6XTPoqZrDJgAAxH0AAAwAAAAAAAAAAAAAAKSB7xgQAFBTU3R5bGUu
cHNtMVBLBQYAAAAACQAJAKgCAADcPxAAAAA=
'@
New-Item -ItemType Directory -Path $root,$stage,$backup -Force | Out-Null
try {
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $zip=Join-Path $stage 'payload.zip'
    [IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String($payload))
    $unpack=Join-Path $stage 'files';[IO.Compression.ZipFile]::ExtractToDirectory($zip,$unpack)
    foreach($name in @('PSStyle.psm1','Community.ps1')){
        $tokens=$null;$errors=$null
        [void][System.Management.Automation.Language.Parser]::ParseFile((Join-Path $unpack $name),[ref]$tokens,[ref]$errors)
        if($errors.Count){throw ('Syntax check failed: '+$name+' '+(($errors|ForEach-Object Message)-join '; '))}
    }
    $tracked=@('PSStyle.psm1','Community.ps1','config.json','community.json','terminal-original.json')
    foreach($name in $tracked){$old=Join-Path $root $name;if(Test-Path -LiteralPath $old){Copy-Item -LiteralPath $old -Destination (Join-Path $backup $name)}}
    $hadProfile=Test-Path -LiteralPath $profilePath
    if($hadProfile){Copy-Item -LiteralPath $profilePath -Destination (Join-Path $backup 'profile.ps1')}
    $settingsCandidates=@((Join-Path $env:LOCALAPPDATA 'Packages\Microsoft.WindowsTerminal_8wekyb3d8bbwe\LocalState\settings.json'),(Join-Path $env:LOCALAPPDATA 'Microsoft\Windows Terminal\settings.json'),(Join-Path $env:LOCALAPPDATA 'Packages\Microsoft.WindowsTerminalPreview_8wekyb3d8bbwe\LocalState\settings.json'))
    $terminalPath=$settingsCandidates | Where-Object {Test-Path -LiteralPath $_} | Select-Object -First 1
    if(-not $terminalPath){$terminalPath=if(Get-AppxPackage -Name Microsoft.WindowsTerminal -ErrorAction SilentlyContinue){$settingsCandidates[0]}elseif(Get-AppxPackage -Name Microsoft.WindowsTerminalPreview -ErrorAction SilentlyContinue){$settingsCandidates[2]}else{$settingsCandidates[1]}}
    $hadTerminal=Test-Path -LiteralPath $terminalPath
    if($hadTerminal){Copy-Item -LiteralPath $terminalPath -Destination (Join-Path $backup 'terminal-settings.json')}
    $cfg=Join-Path $root 'community.json'
    $state=if(Test-Path -LiteralPath $cfg){Get-Content -LiteralPath $cfg -Raw | ConvertFrom-Json}else{[pscustomobject]@{enabled=$true;overlay='snow';decoration='none';density=35}}
    $state.PSObject.Properties.Remove('position')
    foreach($pair in @(@('enabled',$true),@('overlay','snow'),@('decoration','none'),@('density',35))){if(-not $state.PSObject.Properties[$pair[0]]){$state|Add-Member NoteProperty $pair[0] $pair[1]}}
    if($state.overlay -notin @('none','snow','flakes','leaves','sparkles')){$state.overlay='snow'}
    if($state.decoration -notin @('none','snow','leaves')){$state.decoration='none'}
    $state.density=[Math]::Max(5,[Math]::Min(70,[int]$state.density))
    # Stop only the old RCMDS helper, not other PowerShell processes.
    $installed=$true
    $state.enabled=$false;$state|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $cfg -Encoding UTF8
    Start-Sleep -Milliseconds 400
    try{Get-CimInstance Win32_Process -Filter "Name='powershell.exe'"|Where-Object {$_.ProcessId -ne $PID -and $_.CommandLine -and $_.CommandLine.Contains((Join-Path $root 'Community.ps1')) -and $_.CommandLine -match '(?i)\s-Target\s+\d+'}|ForEach-Object {Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue}}catch{}
    foreach($file in Get-ChildItem -LiteralPath $unpack -Recurse -File){
        $relative=$file.FullName.Substring($unpack.Length+1);$dest=Join-Path $root $relative
        New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force|Out-Null
        if($relative -like 'CommunityAssets\Wallpapers\*' -and (Test-Path -LiteralPath $dest)){continue}
        Copy-Item -LiteralPath $file.FullName -Destination $dest -Force
    }
    $state.enabled=$true;$state|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $cfg -Encoding UTF8
    Import-Module $module -Global -Force -ErrorAction Stop
    Initialize-PSStyle
    Set-RCMDSStartupProfiles
    # Explicit Terminal profile startup works even when a user's profile is restricted.
    # Add a small guarded hook for directly opened Windows PowerShell sessions as well.
    if(-not $hadProfile -or -not (Select-String -LiteralPath $profilePath -SimpleMatch '# RCMDS 1.1 customization loader' -Quiet)){
        $hook=@'
# RCMDS 1.1 customization loader
if ($env:WT_SESSION -and $Host.Name -eq 'ConsoleHost') {
    $rcmdsModulePath=Join-Path $env:LOCALAPPDATA 'PSStyle\PSStyle.psm1'
    if (Test-Path -LiteralPath $rcmdsModulePath) {
        if(-not (Get-Module PSStyle)){Import-Module $rcmdsModulePath -ErrorAction Stop}
        Start-RCMDS
    }
}
'@
        New-Item -ItemType Directory -Path (Split-Path -Parent $profilePath) -Force|Out-Null
        $changedProfile=$true;Add-Content -LiteralPath $profilePath -Value ("`r`n"+$hook) -Encoding UTF8
    }
    Write-Host 'SUCCESS! RCMDS 1.1 installed and unlocked.' -ForegroundColor Green
    Write-Host 'Default profile: RCMDS 1.1 | All commands: rcmds help' -ForegroundColor Cyan
    Write-Host ('Backup: '+$backup) -ForegroundColor DarkGray
}catch{
    if($installed){
        foreach($name in $tracked){$saved=Join-Path $backup $name;$dest=Join-Path $root $name;if(Test-Path -LiteralPath $saved){Copy-Item -LiteralPath $saved -Destination $dest -Force}else{Remove-Item -LiteralPath $dest -Force -ErrorAction SilentlyContinue}}
        if($hadTerminal){Copy-Item -LiteralPath (Join-Path $backup 'terminal-settings.json') -Destination $terminalPath -Force}else{Remove-Item -LiteralPath $terminalPath -Force -ErrorAction SilentlyContinue}
        if($changedProfile){if($hadProfile){Copy-Item -LiteralPath (Join-Path $backup 'profile.ps1') -Destination $profilePath -Force}else{Remove-Item -LiteralPath $profilePath -Force -ErrorAction SilentlyContinue}}
    }
    throw
}finally{Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue}
if(-not $NoLaunch){try{rcmds open}catch{Write-Warning 'Installed. Open Windows Terminal and select RCMDS 1.1 from the profile menu.'}}
